/* ==================== drill library ==================== */
/* metric: 'makes' = attempts and makes (shooting and finishing), 'reps' = good reps out of reps.
   partner: true only when the drill cannot be done without another player. soloVariant is always written. */
function DR(o) {
  return {
    id: 'd-' + o.slug, name: o.name, category: o.cat, difficulty: o.diff, secondary: o.sec || [],
    objective: o.obj, instructions: o.ins, coaching: o.coach || [], mistakes: o.mist || [],
    progressions: o.prog || [], regressions: o.reg || [],
    equipment: o.eq || ['Ball', 'Hoop'], minutes: o.min, sets: o.sets, attempts: o.att, metric: o.metric || 'makes',
    zone: o.zone || null, partner: !!o.partner, soloVariant: o.solo, partnerVariant: o.pv || null,
    favorite: false, custom: false, video: '', created: 0
  };
}
